effect.shader:

      mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }
               vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

       vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

        void main() {

            highp mat3 rgb2yuv = mat3(
                 0.299,     0.587,    0.114,
                -0.14713,  -0.28886,  0.436,
                 0.615,    -0.51499, -0.10001
            );
            highp mat3 yuv2rgb = mat3(
                1.0,  0.0,      1.13983,
                1.0, -0.39465, -0.58060,
                1.0,  2.03211,  0.0
            );
            float rad = hue * 0.0174533;
            highp mat3 huemat = mat3(
                1.0,  0.0,       0.0,
                0.0,  cos(rad),  sin(rad),
                0.0,  -sin(rad), cos(rad)
            );

            vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm.st);

                vec2 TanRyu = acScreenNorm;
                // TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
                // TanRyu.y*=acLayerSize.y/acLayerSize.x;
                TanRyu += vec2((0.0+(position.x/15.0)), (0.0+(position.y/15.0)))*vec2(-1.,1.)/500.;
                // vec2 scaleVec;
                // scaleVec = vec2(1.0*stretch.x,1.0*stretch.y);
                // TanRyu /= scaleVec;

            // vec2 UV = acScreenNorm;
            // vec2 center = acLayerCenterNorm-(centerPoint/1000. * vec2(-1.,1.));

            // UV -= center;
            // UV.x *= acScreenSize.x / acScreenSize.y;

            ////// OLD
            vec4 baseColor;
            vec4 compColorr;
            vec4 shadow;
            // float rr = length(rrr - UV);
            float rr = length(rrr - acScreenNorm.st);

            baseColor = texture2DCv(inputImg.texture,acScreenNorm.st)*calpha;
            compColorr = texture2DCv(vblur.texture, TanRyu);
            ///SATVIB
            highp vec3 rgb = compColorr.rgb ;
            highp vec3 yuv = rgb * rgb2yuv;

            yuv = yuv * huemat; //HUE

            float origSat = min(1.0,length(yuv.yz)*2.5); //
            vec2 satUV = yuv.yz * satvib.y;
            yuv.yz = mix(satUV,yuv.yz,origSat);
            yuv.yz = yuv.yz * (satvib.x+1.0);
            rgb = yuv * yuv2rgb;

            vec4 newComp = vec4(rgb, compColorr.a);

            // compColorr = texture2DCv(vblur.texture, acScreenNorm.st);

            shadow = newComp * (vec4(0.,0.,0,1.0) * higsha.y) * compColorr.a;
            // shadow = compColorr * (vec4(0.,0.,0,1.0) * higsha.y) * compColorr.a;
            vec4 c = shadow + vec4(1.)*(1.-shadow.a);

            vec4 dblur = vec4(newComp.rgb / compColorr.a,1.) * (rr - 0.5);
            // vec4 dblur = vec4(compColorr.rgb / compColorr.a,1.) * (rr - 0.5);

            vec4 targetLuma = dblur ;
            const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            float luma = dot(targetLuma.rgb, luminanceWeighting);
            float lowThresholdB = (lowThreshold*(1.0+feather))-0.0001;
            float lowThresholdA = lowThresholdB-max(feather,0.00001);
            float highThresholdA = (highThreshold*(1.0+feather)-feather)+0.0001;
            float highThresholdB = highThresholdA+max(feather,0.00001);
            float lowBlend = smoothstep( lowThresholdA, lowThresholdB, luma );
            float highBlend = 1. - smoothstep( highThresholdA, highThresholdB, luma );
            float lumafx = min(lowBlend,highBlend);
            vec4 dblurr = targetLuma;
            if (thrs) {
            dblurr *= lumafx; }

            ///OLD
            vec4 blendC = vec4((dblurr.rgb/dblurr.a)*c.rgb,1.0) * dblurr.a;
            vec4 resultfinalx = vec4(color.rgb,dblurr.a) * dblurr.a;
            // vec4 resultfinalx = vec4(cross(color.rgb,blendC.rgb),1.0) * dblurr.a;
            // vec4 resultfinalx = vec4(saturate(color.rgb,blendC.rgb),1.0) * dblurr.a;
            // vec4 resultfinalx = vec4(color.rgb*blendC.rgb, alpc) * dblurr.a;
            vec4 resultfinal = mix(blendC, resultfinalx, alpb ) * dblurr.a;
            vec4 rrfinal = cblend? resultfinal : blendC;
            // vec4 resultfinal = vec4(saturate(color.rgb*blendC.rgb), progressa) * dblurr.a;

            // vec4 resultfinal = vec4((dblurr.rgb/dblurr.a)*c.rgb,1.0) * dblurr.a;
            // vec4 blendC = vec3(resultfinal.rgb, progressa) * dblurr.a;

            vec4 L2 = ((baseColor*higsha.x) + (rrfinal*oalpha)) * compColorr.a;
            L2 += baseColor;

            vec4 L1 = texture2DCv(hblur.texture, acScreenNorm.st);
            L1 = vec4(vec3(0.,0.,0), L1.a);
            L1 *= alphaa;

            gl_FragColor = sshadow? newLayer(L1, L2) : L2;

        }
